// 1. the N+1 version: one query for the merchants, then one per merchant
val merchants = conn.prepareStatement("SELECT merchant_id, name FROM merchants ORDER BY merchant_id")
    .executeQuery().use { rs -> buildList { while (rs.next()) add(rs.getLong(1) to rs.getString(2)) } }
val latest = conn.prepareStatement(
    "SELECT payment_id, amount_minor FROM payments " +
        "WHERE merchant_id = ? AND status = 'succeeded' " +
        "ORDER BY created_at DESC, payment_id DESC LIMIT 1")
val rows = merchants.map { (id, name) ->
    latest.setLong(1, id)                                     // one round trip per merchant
    latest.executeQuery().use { rs -> Triple(id, name, if (rs.next()) rs.getLong(1) else null) }
}
